// =====================================================================================
// ASSET PACK v3 — second-generation raster painter.
// Parts follow the PART SHEET topology (L/R halves, 4 false faces, eye shard, mirror shard, ghost).
// Big planes + ink line-work + lit bevel + violet rim are painted ONCE into cached bitmaps
// (S=.62 working scale, 3 mip levels). Eyes / smiles are separate prepared sprites so the
// expression system never has to draw a face. Hidden material is over-painted past every
// shared edge (planes overshoot the outline) so articulation never exposes a hole.
// =====================================================================================
const A_path=d=>new Path2D(d);
function A_plane(g,d,x0,y0,x1,y1,c0,c1,a){
  const gr=g.createLinearGradient(x0,y0,x1,y1);gr.addColorStop(0,c0);gr.addColorStop(1,c1);
  g.save();if(a!==undefined)g.globalAlpha=a;g.fillStyle=gr;g.fill(A_path(d));g.restore();
}
function A_line(g,d,w,col,a){g.save();g.globalAlpha=a===undefined?1:a;g.strokeStyle=col;g.lineWidth=w;g.lineJoin='round';g.lineCap='round';g.stroke(A_path(d));g.restore()}
function A_shell(g,O,o){
  g.save();g.lineJoin='round';
  g.shadowColor=o.glow;g.shadowBlur=o.gb||20;g.strokeStyle=o.rim;g.lineWidth=7;g.stroke(O);
  g.shadowBlur=0;g.shadowColor='rgba(0,0,0,0)';g.lineWidth=3.2;g.stroke(O);
  g.clip(O);
  g.fillStyle=o.base;g.fillRect(-3000,-3000,7000,7000);
  if(o.pre)o.pre(g);
  if(o.planes){for(const p of o.planes)A_plane(g,p[0],p[1],p[2],p[3],p[4],p[5],p[6],p[7]);
    g.strokeStyle='rgba(12,6,34,.4)';g.lineWidth=2.2;for(const p of o.planes)g.stroke(A_path(p[0]))}
  if(o.tail)o.tail(g);
  g.save();g.shadowColor='rgba(34,12,92,.8)';g.shadowBlur=o.depth||22;g.strokeStyle='rgba(34,12,92,.5)';g.lineWidth=8;g.stroke(O);g.restore();
  const b=o.bv,gr=g.createLinearGradient(b[0],b[1],b[2],b[3]);gr.addColorStop(0,'rgba(255,255,255,.92)');gr.addColorStop(1,'rgba(200,160,255,.32)');
  g.strokeStyle=gr;g.lineWidth=o.bw||17;g.stroke(O);
  g.strokeStyle='#07040f';g.lineWidth=11;g.stroke(O);
  g.restore();
}
function drawEye2(g,x,y,w,h,ang,pal,brow,ix,wing,lid){
  lid=lid||1;const Pp=PAL[pal];g.save();g.translate(x,y);g.rotate(ang);
  let gr=g.createRadialGradient(0,0,h*.3,0,0,w*.8);gr.addColorStop(0,'rgba(44,16,104,.5)');gr.addColorStop(1,'rgba(44,16,104,0)');g.fillStyle=gr;g.fillRect(-w,-w,w*2,w*2);
  if(brow){g.fillStyle='#07040f';g.beginPath();g.moveTo(-w*.66,-h*.3);g.quadraticCurveTo(-w*.02,-h*2.1,w*.66,-h*.52);g.lineTo(w*.58,-h*.04);g.quadraticCurveTo(0,-h*1.32,-w*.6,0);g.closePath();g.fill();
    g.strokeStyle='rgba(255,255,255,.35)';g.lineWidth=1.6;g.beginPath();g.moveTo(-w*.6,-h*.44);g.quadraticCurveTo(-w*.02,-h*2.22,w*.64,-h*.64);g.stroke()}
  const top=-h*1.3*lid;
  const path=()=>{g.beginPath();g.moveTo(-w/2,h*.06);g.quadraticCurveTo(-w*.08,top,w/2,-h*.1);g.quadraticCurveTo(w*.02,h*.92,-w/2,h*.06);g.closePath()};
  path();gr=g.createLinearGradient(0,top*.5,0,h*.6);gr.addColorStop(0,Pp.s1);gr.addColorStop(1,Pp.s0);g.fillStyle=gr;g.fill();
  g.save();g.clip();
  const ir=h*.78,cxi=ix*w;
  gr=g.createRadialGradient(cxi,h*.05,1,cxi,0,ir);gr.addColorStop(0,Pp.i0);gr.addColorStop(.55,Pp.i1);gr.addColorStop(1,Pp.i2);
  g.fillStyle=gr;g.beginPath();g.arc(cxi,0,ir,0,TAU);g.fill();g.strokeStyle='rgba(20,6,60,.85)';g.lineWidth=h*.1;g.stroke();
  g.fillStyle='#0d0328';g.beginPath();g.ellipse(cxi,h*.02,ir*.3,ir*.5,0,0,TAU);g.fill();
  g.fillStyle='rgba(255,255,255,.96)';g.beginPath();g.arc(cxi-ir*.34,-ir*.36,ir*.17,0,TAU);g.fill();
  g.fillStyle='rgba(255,255,255,.55)';g.beginPath();g.arc(cxi+ir*.3,ir*.3,ir*.08,0,TAU);g.fill();
  gr=g.createLinearGradient(0,top,0,0);gr.addColorStop(0,'rgba(24,6,70,.75)');gr.addColorStop(1,'rgba(24,6,70,0)');g.fillStyle=gr;g.fillRect(-w,top,w*2,-top);
  g.restore();
  g.lineJoin='round';g.lineCap='round';g.strokeStyle='#07040f';g.lineWidth=Math.max(3,h*.2);
  g.beginPath();g.moveTo(-w/2,h*.06);g.quadraticCurveTo(-w*.08,top,w/2,-h*.1);g.stroke();
  g.lineWidth=Math.max(2,h*.08);g.beginPath();g.moveTo(-w/2,h*.06);g.quadraticCurveTo(w*.02,h*.92,w/2,-h*.1);g.stroke();
  const sgn=wing>0?1:-1,wx=sgn>0?w/2:-w/2,wy=sgn>0?-h*.1:h*.06;
  g.fillStyle='#07040f';g.beginPath();g.moveTo(wx,wy-h*.12);g.lineTo(wx+sgn*w*.2,wy-h*.5);g.lineTo(wx+sgn*w*.02,wy+h*.1);g.closePath();g.fill();
  g.restore();
}
function drawSmile2(g,a,c,b,t,hook){
  g.fillStyle='#07040f';g.beginPath();g.moveTo(a[0],a[1]);g.quadraticCurveTo(c[0],c[1],b[0],b[1]);g.quadraticCurveTo(c[0]+(b[0]-a[0])*.02,c[1]+t*2.1,a[0],a[1]);g.closePath();g.fill();
  if(hook){g.strokeStyle='#07040f';g.lineWidth=t*.45;g.lineCap='round';g.beginPath();g.moveTo(a[0]-t*.2,a[1]-t*1.6);g.quadraticCurveTo(a[0]+t*.3,a[1]-t*.6,a[0]+t*.9,a[1]+t*.9);g.stroke()}
}
function A_plate(id,spec){
  const pts=PTS[id],info=pinfo(pts);PLI[id]=info;
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;pts.forEach(p=>{x0=Math.min(x0,p[0]);y0=Math.min(y0,p[1]);x1=Math.max(x1,p[0]);y1=Math.max(y1,p[1])});
  const O=new Path2D();pts.forEach((p,i)=>i?O.lineTo(p[0],p[1]):O.moveTo(p[0],p[1]));O.closePath();
  const ca=Math.cos(info.ang),sa=Math.sin(info.ang);let mn=1e9,mx=-1e9,al=1e9,ah=-1e9;
  pts.forEach(p=>{const dx=p[0]-info.cx,dy=p[1]-info.cy,d=-dx*sa+dy*ca,e=dx*ca+dy*sa;mn=Math.min(mn,d);mx=Math.max(mx,d);al=Math.min(al,e);ah=Math.max(ah,e)});
  const ey=spec.eye;
  bake(id,[x0-44,y0-44,x1+44,y1+44],g=>{
    A_shell(g,O,{base:spec.base,glow:spec.glow,rim:spec.rim,depth:16,bw:15,bv:[x0,y0,x1,y1],
      pre:g=>{g.save();g.translate(info.cx,info.cy);g.rotate(info.ang);
        for(const b of spec.bands){const v0=lerp(mn,mx,b[0]),v1=lerp(mn,mx,b[1]),gr=g.createLinearGradient(al,0,ah,0);gr.addColorStop(0,b[2]);gr.addColorStop(1,b[3]);
          g.fillStyle=gr;g.fillRect(al-50,v0,ah-al+100,v1-v0);g.fillStyle='rgba(255,255,255,.55)';g.fillRect(al-50,v0,ah-al+100,2);g.fillStyle='rgba(10,5,30,.45)';g.fillRect(al-50,v1-2,ah-al+100,2)}
        for(const w of spec.wedges){g.beginPath();w.p.forEach((q,i)=>{const u=lerp(al,ah,q[0]),v=lerp(mn,mx,q[1]);i?g.lineTo(u,v):g.moveTo(u,v)});g.closePath();g.fillStyle=w.c;g.fill()}
        g.fillStyle=spec.tint;g.fillRect(al-60,mn-60,ah-al+120,mx-mn+120);g.restore()},
      tail:g=>{const gr=g.createRadialGradient(ey.x,ey.y,4,ey.x,ey.y,ey.w*.8);gr.addColorStop(0,'rgba(240,234,255,.5)');gr.addColorStop(1,'rgba(240,234,255,0)');g.fillStyle=gr;g.fillRect(ey.x-ey.w,ey.y-ey.w,ey.w*2,ey.w*2)}});
    spec.stars.forEach(s=>star(g,s[0],s[1],s[2]));
  },{s:.62,ax:info.cx,ay:info.cy});
  bake(id+'e',[ey.x-ey.w*.95,ey.y-ey.w*.95,ey.x+ey.w*.95,ey.y+ey.w*.95],g=>drawEye2(g,ey.x,ey.y,ey.w,ey.h,ey.ang,ey.pal,false,ey.ix,ey.wing,ey.lid),{s:.7,ax:ey.x,ay:ey.y});
  const sm=spec.smile;
  if(sm)bake(id+'s',[sm[0][0]-30,Math.min(sm[0][1],sm[1][1])-30,sm[2][0]+40,sm[2][1]+80],g=>drawSmile2(g,sm[0],sm[1],sm[2],sm[3],true),{s:.7,ax:sm[2][0],ay:sm[2][1]});
}
